CREATE DATABASE INAI_Coffee;
GO
USE INAI_Coffee;
GO
CREATE TABLE Kategoriya (id INT IDENTITY(1,1) PRIMARY KEY, nazvanie NVARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE Klient (id INT IDENTITY(1,1) PRIMARY KEY, fio NVARCHAR(100) NOT NULL, telefon NVARCHAR(20) UNIQUE, bonus INT DEFAULT 0 CHECK(bonus>=0), email NVARCHAR(100) CHECK(email LIKE '%@%'));
CREATE TABLE Sotrudnik (id INT IDENTITY(1,1) PRIMARY KEY, fio NVARCHAR(100) NOT NULL, id_boss INT REFERENCES Sotrudnik(id));
CREATE TABLE Tovar (id INT IDENTITY(1,1) PRIMARY KEY, nazvanie NVARCHAR(100) NOT NULL UNIQUE, cena DECIMAL(10,2) NOT NULL CHECK(cena>0), id_kategoriya INT REFERENCES Kategoriya(id));
CREATE TABLE Zakaz (id INT IDENTITY(1,1) PRIMARY KEY, id_klient INT NOT NULL REFERENCES Klient(id), id_sotrudnik INT REFERENCES Sotrudnik(id), data DATE DEFAULT CAST(GETDATE() AS DATE) NOT NULL, summa DECIMAL(10,2) NOT NULL CHECK(summa>=0));
CREATE TABLE Sostav_zakaza (id INT IDENTITY(1,1) PRIMARY KEY,id_zakaz INT NOT NULL REFERENCES Zakaz(id),id_tovar INT NOT NULL REFERENCES Tovar(id),qty INT NOT NULL CHECK(qty>0),price DECIMAL(10,2) NOT NULL CHECK(price>0));
